CREATE INDEX IF NOT EXISTS "agent_events_operator_fallback" ON "agent_events" USING btree ("agent_id",(data->>'operatorFallback')) WHERE "agent_events"."kind" = 'typed' and data->>'operatorFallback' is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "agent_events_operator_delivery" ON "agent_events" USING btree ("agent_id","job_id",(data->'operatorDelivery'->>'id')) WHERE data->'operatorDelivery'->>'id' is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "agent_events_operator_evidence_delivery" ON "agent_events" USING btree ("agent_id",(data->'operatorEvidence'->>'deliveryId')) WHERE data->'operatorEvidence'->>'deliveryId' is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "agent_events_operator_evidence_instance" ON "agent_events" USING btree ("agent_id",(data->'operatorEvidence'->>'instance')) WHERE data->'operatorEvidence'->>'instance' is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "agent_events_operator_recovery_case" ON "agent_events" USING btree ("agent_id",(data->'operatorEvidence'->>'case')) WHERE data->'operatorEvidence'->>'type' = 'program.recovery_ready' and data->'operatorEvidence'->>'case' is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "jobs_agent_conversation_ended" ON "jobs" USING btree ("company_id","agent_id",coalesce("finished_at", "created_at"),"created_at") WHERE "jobs"."kind" = 'conversation' and "jobs"."status" in ('done', 'failed');--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "jobs_agent_conversation_retry_waiting" ON "jobs" USING btree ("company_id","agent_id","created_at") WHERE "jobs"."kind" = 'conversation' and "jobs"."status" = 'queued' and "jobs"."not_before" is not null and "jobs"."continue_of" is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "jobs_agent_conversation_obsolete" ON "jobs" USING btree ("company_id","agent_id",coalesce("finished_at", "created_at"),"created_at") WHERE "jobs"."kind" = 'conversation' and "jobs"."status" = 'obsolete';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "jobs_agent_conversation_finished" ON "jobs" USING btree ("company_id","agent_id","finished_at") WHERE "jobs"."kind" = 'conversation' and "jobs"."started_at" is not null and "jobs"."finished_at" is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "jobs_task_conversation_finished" ON "jobs" USING btree ("company_id","task_id","finished_at") WHERE "jobs"."kind" = 'conversation' and "jobs"."task_id" is not null and "jobs"."started_at" is not null and "jobs"."finished_at" is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "jobs_company_conversation_running" ON "jobs" USING btree ("company_id","agent_id","task_id") WHERE "jobs"."kind" = 'conversation' and "jobs"."status" = 'running';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "program_deliveries_live_not_taken" ON "program_deliveries" USING btree ("created_at") WHERE "program_deliveries"."kind" = 'live' and "program_deliveries"."outcome" = 'not_taken';